declare module "#build/comvi.options" {
  // Generated by the module (src/module.ts): the `comvi` data of nuxt.config every
  // instance starts from, and the default export of `comvi.i18n.ts` (or `() => ({})`).
  export const config: Pick<
    import("@comvi/core").I18nOptions,
    "timeZone" | "fallbackLocale" | "namespaces" | "formats" | "messages"
  >;
  export const options: import("../types").I18nOptionsFactory;
}

declare module "#build/comvi.detection" {
  // Generated by the module (src/module.ts): `localeDetection.resolveAcceptLanguage`
  // copied into the build as source, because a function cannot travel through
  // runtime config. `undefined` when the app set none.
  export const resolveAcceptLanguage: import("../types").ResolveAcceptLanguage | undefined;
}

// The same generated modules under the names the Nitro build knows them by: the module
// registers them as Nitro virtual modules (`nitro:config`), because `#build/*` is refused
// in the Nitro graph. Imported by the server utility only.
declare module "#comvi/options" {
  export * from "#build/comvi.options";
}

declare module "#comvi/detection" {
  export * from "#build/comvi.detection";
}
